1	/**
2	 * cf-extra-routes.ts
3	 *
4	 * CF-native handlers for API endpoints that use raw Express handlers in the
5	 * server package (making them invisible to extractRoutesFromRouter) or depend
6	 * on runtime registries (adapters, plugins) that don't exist in a CF Worker.
7	 *
8	 * Registered in app.ts BEFORE the /api/* catch-all so they shadow the 501.
9	 */
10	
11	import type { Hono } from "hono";
12	import { and, asc, desc, eq, inArray, ne } from "drizzle-orm";
13	import {
14	  agents,
15	  authUsers,
16	  companyMemberships,
17	  companySkills,
18	  invites,
19	  joinRequests,
20	  plugins,
21	} from "@paperclipai/db";
22	import { collapseDuplicatePendingHumanJoinRequests } from "../../../../server/src/lib/join-request-dedupe.js";
23	import { resolveHumanInviteRole } from "../../../../server/src/services/company-member-roles.js";
24	import { getPluginUiContributionMetadata } from "../../../../server/src/services/plugin-loader.js";
25	import { listServerAdapters, isOverridePaused } from "../../../../server/src/adapters/registry.js";
26	import { BUILTIN_ADAPTER_TYPES } from "../../../../server/src/adapters/builtin-adapter-types.js";
27	import { getDisabledAdapterTypes } from "../../../../server/src/services/adapter-plugin-store.js";
28	import { createHyperdriveDb } from "../db/hyperdrive.js";
29	import type { Env } from "./env.js";
30	
31	// ---------------------------------------------------------------------------
32	// Helpers (inlined from server/src/routes/access.ts — CF-safe subsets)
33	// ---------------------------------------------------------------------------
34	
35	function extractInviteMessage(invite: {
36	  defaultsPayload: unknown;
37	}): string | null {
38	  const raw = invite.defaultsPayload;
39	  if (!raw || typeof raw !== "object" || Array.isArray(raw)) return null;
40	  const msg = (raw as Record<string, unknown>).agentMessage;
41	  if (typeof msg !== "string") return null;
42	  const trimmed = msg.trim();
43	  return trimmed.length ? trimmed : null;
44	}
45	
46	type SkillSourceBadge = "paperclip" | "skills_sh" | "github" | "url" | "local" | "catalog";
47	
48	function deriveSkillSource(skill: {
49	  sourceType: string;
50	  sourceLocator: string | null;
51	  metadata: unknown;
52	}): {
53	  editable: boolean;
54	  editableReason: string | null;
55	  sourceLabel: string | null;
56	  sourceBadge: SkillSourceBadge;
57	  sourcePath: null;
58	} {
59	  const meta =
60	    skill.metadata && typeof skill.metadata === "object" && !Array.isArray(skill.metadata)
61	      ? (skill.metadata as Record<string, unknown>)
62	      : {};
63	
64	  if (meta.sourceKind === "paperclip_bundled") {
65	    return { editable: false, editableReason: "Bundled Paperclip skills are read-only.", sourceLabel: "Paperclip bundled", sourceBadge: "paperclip", sourcePath: null };
66	  }
67	  if (skill.sourceType === "skills_sh") {
68	    return { editable: false, editableReason: "Skills.sh-managed skills are read-only.", sourceLabel: skill.sourceLocator, sourceBadge: "skills_sh", sourcePath: null };
69	  }
70	  if (skill.sourceType === "github") {
71	    const owner = typeof meta.owner === "string" ? meta.owner : null;
72	    const repo = typeof meta.repo === "string" ? meta.repo : null;
73	    return { editable: false, editableReason: "Remote GitHub skills are read-only.", sourceLabel: owner && repo ? `${owner}/${repo}` : skill.sourceLocator, sourceBadge: "github", sourcePath: null };
74	  }
75	  if (skill.sourceType === "url") {
76	    return { editable: false, editableReason: "URL-based skills are read-only.", sourceLabel: skill.sourceLocator, sourceBadge: "url", sourcePath: null };
77	  }
78	  if (skill.sourceType === "local_path") {
79	    return { editable: true, editableReason: null, sourceLabel: skill.sourceLocator, sourceBadge: "local", sourcePath: null };
80	  }
81	  return { editable: false, editableReason: "This skill source is read-only.", sourceLabel: skill.sourceLocator, sourceBadge: "catalog", sourcePath: null };
82	}
83	
84	// ---------------------------------------------------------------------------
85	// Route registration
86	// ---------------------------------------------------------------------------
87	
88	export function registerCfExtraRoutes(app: Hono<{ Bindings: Env }>): void {
89	  // -------------------------------------------------------------------------
90	  // GET /api/adapters — built-in adapters from registry (external adapters
91	  // require FS-backed plugin store not available in CF; built-ins always load)
92	  // -------------------------------------------------------------------------
93	  app.get("/api/adapters", (c) => {
94	    const adapters = listServerAdapters();
95	    const disabledSet = new Set(getDisabledAdapterTypes());
96	    const result = adapters
97	      .map((adapter) => ({
98	        type: adapter.type,
99	        label: adapter.type,
100	        source: "builtin" as const,
101	        modelsCount: (adapter.models ?? []).length,
102	        loaded: true,
103	        disabled: disabledSet.has(adapter.type),
104	        capabilities: {
105	          supportsInstructionsBundle: adapter.supportsInstructionsBundle ?? false,
106	          supportsSkills: Boolean(adapter.listSkills || adapter.syncSkills),
107	          supportsLocalAgentJwt: adapter.supportsLocalAgentJwt ?? false,
108	          requiresMaterializedRuntimeSkills: adapter.requiresMaterializedRuntimeSkills ?? false,
109	        },
110	        overridePaused: BUILTIN_ADAPTER_TYPES.has(adapter.type)
111	          ? isOverridePaused(adapter.type)
112	          : undefined,
113	      }))
114	      .sort((a, b) => a.type.localeCompare(b.type));
115	    return c.json(result);
116	  });
117	
118	  // -------------------------------------------------------------------------
119	  // GET /api/plugins — list installed plugins from DB (registry state comes
120	  // from manifestJson stored at install time; worker processes not available)
121	  // GET /api/plugins/ui-contributions — derive from manifestJson in DB
122	  // -------------------------------------------------------------------------
123	  app.get("/api/plugins", async (c) => {
124	    const db = createHyperdriveDb(c.env.HYPERDRIVE);
125	    const rows = await db
126	      .select()
127	      .from(plugins)
128	      .where(ne(plugins.status, "uninstalled"))
129	      .orderBy(asc(plugins.installOrder));
130	    return c.json(rows);
131	  });
132	
133	  app.get("/api/plugins/ui-contributions", async (c) => {
134	    const db = createHyperdriveDb(c.env.HYPERDRIVE);
135	    const rows = await db
136	      .select()
137	      .from(plugins)
138	      .where(ne(plugins.status, "uninstalled"))
139	      .orderBy(asc(plugins.installOrder));
140	
141	    const contributions = rows.flatMap((plugin) => {
142	      const manifest = plugin.manifestJson;
143	      if (!manifest) return [];
144	      const uiMetadata = getPluginUiContributionMetadata(manifest);
145	      if (!uiMetadata) return [];
146	      return [{
147	        pluginId: plugin.id,
148	        pluginKey: plugin.pluginKey,
149	        displayName: manifest.displayName,
150	        version: plugin.version,
151	        updatedAt: plugin.updatedAt.toISOString(),
152	        uiEntryFile: uiMetadata.uiEntryFile,
153	        slots: uiMetadata.slots,
154	        launchers: uiMetadata.launchers,
155	      }];
156	    });
157	    return c.json(contributions);
158	  });
159	
160	  // -------------------------------------------------------------------------
161	  // GET /api/companies/:companyId/skills
162	  //
163	  // Mirrors companySkillService.list() but skips ensureSkillInventoryCurrent
164	  // (which uses node:fs) since CF Workers have no host filesystem.
165	  // -------------------------------------------------------------------------
166	  app.get("/api/companies/:companyId/skills", async (c) => {
167	    const companyId = c.req.param("companyId");
168	    const db = createHyperdriveDb(c.env.HYPERDRIVE);
169	
170	    const rows = await db
171	      .select({
172	        id: companySkills.id,
173	        companyId: companySkills.companyId,
174	        key: companySkills.key,
175	        slug: companySkills.slug,
176	        name: companySkills.name,
177	        description: companySkills.description,
178	        sourceType: companySkills.sourceType,
179	        sourceLocator: companySkills.sourceLocator,
180	        sourceRef: companySkills.sourceRef,
181	        trustLevel: companySkills.trustLevel,
182	        compatibility: companySkills.compatibility,
183	        fileInventory: companySkills.fileInventory,
184	        metadata: companySkills.metadata,
185	        createdAt: companySkills.createdAt,
186	        updatedAt: companySkills.updatedAt,
187	      })
188	      .from(companySkills)
189	      .where(eq(companySkills.companyId, companyId))
190	      .orderBy(asc(companySkills.name), asc(companySkills.key));
191	
192	    // attachedAgentCount: resolveDesiredSkillKeys uses non-exported internals;
193	    // query agents and do a simple adapterConfig scan instead.
194	    const agentRows = await db
195	      .select({ adapterConfig: agents.adapterConfig })
196	      .from(agents)
197	      .where(eq(agents.companyId, companyId));
198	
199	    const result = rows.map((row) => {
200	      const source = deriveSkillSource({
201	        sourceType: row.sourceType,
202	        sourceLocator: row.sourceLocator ?? null,
203	        metadata: row.metadata,
204	      });
205	
206	      const attachedAgentCount = agentRows.filter((agent) => {
207	        const cfg = agent.adapterConfig;
208	        if (!cfg || typeof cfg !== "object" || Array.isArray(cfg)) return false;
209	        const skillsValue = (cfg as Record<string, unknown>).skills;
210	        if (!Array.isArray(skillsValue)) return false;
211	        return skillsValue.some(
212	          (entry) =>
213	            (typeof entry === "string" && entry === row.key) ||
214	            (entry && typeof entry === "object" && (entry as Record<string, unknown>).key === row.key),
215	        );
216	      }).length;
217	
218	      return {
219	        id: row.id,
220	        companyId: row.companyId,
221	        key: row.key,
222	        slug: row.slug,
223	        name: row.name,
224	        description: row.description ?? null,
225	        sourceType: row.sourceType,
226	        sourceLocator: row.sourceLocator ?? null,
227	        sourceRef: row.sourceRef ?? null,
228	        trustLevel: row.trustLevel,
229	        compatibility: row.compatibility,
230	        fileInventory: Array.isArray(row.fileInventory) ? row.fileInventory : [],
231	        metadata: row.metadata ?? null,
232	        createdAt: row.createdAt,
233	        updatedAt: row.updatedAt,
234	        attachedAgentCount,
235	        ...source,
236	      };
237	    });
238	
239	    return c.json(result);
240	  });
