242	  // -------------------------------------------------------------------------
243	  // GET /api/companies/:companyId/join-requests
244	  // -------------------------------------------------------------------------
245	  app.get("/api/companies/:companyId/join-requests", async (c) => {
246	    const companyId = c.req.param("companyId");
247	    const statusFilter = c.req.query("status");
248	    const requestTypeFilter = c.req.query("requestType");
249	    const db = createHyperdriveDb(c.env.HYPERDRIVE);
250	
251	    const allRows = await db
252	      .select()
253	      .from(joinRequests)
254	      .where(eq(joinRequests.companyId, companyId))
255	      .orderBy(desc(joinRequests.createdAt));
256	
257	    const rows = collapseDuplicatePendingHumanJoinRequests(allRows);
258	
259	    const inviteIds = [...new Set(rows.map((r) => r.inviteId))];
260	    const inviteRows = inviteIds.length
261	      ? await db.select().from(invites).where(inArray(invites.id, inviteIds))
262	      : [];
263	    const inviteMap = new Map(inviteRows.map((inv) => [inv.id, inv]));
264	
265	    const userIds = [
266	      ...new Set(
267	        [
268	          ...rows.map((r) => r.requestingUserId),
269	          ...rows.map((r) => r.approvedByUserId),
270	          ...rows.map((r) => r.rejectedByUserId),
271	          ...inviteRows.map((inv) => inv.invitedByUserId),
272	        ].filter((id): id is string => Boolean(id)),
273	      ),
274	    ];
275	    const userRows = userIds.length
276	      ? await db
277	          .select({ id: authUsers.id, email: authUsers.email, name: authUsers.name, image: authUsers.image })
278	          .from(authUsers)
279	          .where(inArray(authUsers.id, userIds))
280	      : [];
281	    const userMap = new Map(
282	      userRows.map((u) => [u.id, { id: u.id, email: u.email ?? null, name: u.name ?? null, image: u.image ?? null }]),
283	    );
284	
285	    const toUser = (id: string | null) => (id ? (userMap.get(id) ?? null) : null);
286	
287	    const filtered = rows
288	      .map((row) => {
289	        const { claimSecretHash: _ch, ...safe } = row;
290	        const inv = inviteMap.get(row.inviteId) ?? null;
291	        return {
292	          ...safe,
293	          requesterUser: toUser(row.requestingUserId),
294	          approvedByUser: toUser(row.approvedByUserId),
295	          rejectedByUser: toUser(row.rejectedByUserId),
296	          invite: inv
297	            ? {
298	                id: inv.id,
299	                inviteType: inv.inviteType,
300	                allowedJoinTypes: inv.allowedJoinTypes,
301	                humanRole: resolveHumanInviteRole(inv.defaultsPayload as Record<string, unknown> | null),
302	                inviteMessage: extractInviteMessage(inv),
303	                createdAt: inv.createdAt,
304	                expiresAt: inv.expiresAt,
305	                revokedAt: inv.revokedAt,
306	                acceptedAt: inv.acceptedAt,
307	                invitedByUser: toUser(inv.invitedByUserId),
308	              }
309	            : null,
310	        };
311	      })
312	      .filter((row) => {
313	        if (statusFilter && row.status !== statusFilter) return false;
314	        if (requestTypeFilter && row.requestType !== requestTypeFilter) return false;
315	        return true;
316	      });
317	
318	    return c.json(filtered);
319	  });
320	
321	  // -------------------------------------------------------------------------
322	  // GET /api/companies/:companyId/user-directory
323	  // -------------------------------------------------------------------------
324	  app.get("/api/companies/:companyId/user-directory", async (c) => {
325	    const companyId = c.req.param("companyId");
326	    const db = createHyperdriveDb(c.env.HYPERDRIVE);
327	
328	    const members = await db
329	      .select({ principalId: companyMemberships.principalId, status: companyMemberships.status })
330	      .from(companyMemberships)
331	      .where(
332	        and(
333	          eq(companyMemberships.companyId, companyId),
334	          eq(companyMemberships.principalType, "user"),
335	          eq(companyMemberships.status, "active"),
336	        ),
337	      )
338	      .orderBy(desc(companyMemberships.updatedAt));
339	
340	    const userIds = [...new Set(members.map((m) => m.principalId))];
341	    const userRows = userIds.length
342	      ? await db
343	          .select({ id: authUsers.id, email: authUsers.email, name: authUsers.name, image: authUsers.image })
344	          .from(authUsers)
345	          .where(inArray(authUsers.id, userIds))
346	      : [];
347	    const userMap = new Map(
348	      userRows.map((u) => [u.id, { id: u.id, email: u.email ?? null, name: u.name ?? null, image: u.image ?? null }]),
349	    );
350	
351	    const users = members.map((m) => ({
352	      principalId: m.principalId,
353	      status: "active" as const,
354	      user: userMap.get(m.principalId) ?? null,
355	    }));
356	
357	    return c.json({ users });
358	  });
359	
360	  // -------------------------------------------------------------------------
361	  // GET /api/companies/:companyId/events/ws
362	  //
363	  // CF-native WebSocket upgrade. Without a Durable Object pub/sub bus, the
364	  // connection stays open but receives no server-sent events. The frontend
365	  // treats this as a connected (but silent) event stream, which is better
366	  // than a hard error.
367	  // -------------------------------------------------------------------------
368	  app.get("/api/companies/:companyId/events/ws", (c) => {
369	    const upgrade = c.req.header("Upgrade");
370	    if (!upgrade || upgrade.toLowerCase() !== "websocket") {
371	      return c.text("Expected WebSocket upgrade", 426);
372	    }
373	    const { 0: client, 1: server } = new WebSocketPair();
374	    server.accept();
375	    server.addEventListener("message", () => { /* no-op: no pub/sub wired yet */ });
376	    return new Response(null, { status: 101, webSocket: client });
377	  });
378	}
